private InputSourceReader buildReader(
    SamplerConfig samplerConfig,
    DataSchema dataSchema,
    InputSource inputSource,
    @Nullable InputFormat inputFormat,
    File tempDir
)
{
  final List<String> metricsNames = Arrays.stream(dataSchema.getAggregators())
                                          .map(AggregatorFactory::getName)
                                          .collect(Collectors.toList());
  final InputRowSchema inputRowSchema = new InputRowSchema(
      dataSchema.getTimestampSpec(),
      dataSchema.getDimensionsSpec(),
      metricsNames
  );

  InputSourceReader reader = inputSource.reader(inputRowSchema, inputFormat, tempDir);

  if (samplerConfig.getTimeoutMs() > 0) {
    reader = new TimedShutoffInputSourceReader(reader, DateTimes.nowUtc().plusMillis(samplerConfig.getTimeoutMs()));
  }

  // Validate that JavaScript filters are not used in the sampler endpoint
  // This prevents arbitrary code execution through malicious JavaScript payloads
  validateTransformSpecForJavaScript(dataSchema.getTransformSpec());

  return dataSchema.getTransformSpec().decorate(reader);
}

private void validateTransformSpecForJavaScript(TransformSpec transformSpec)
{
  if (transformSpec == null) {
    return;
  }

  DimFilter filter = transformSpec.getFilter();
  if (filter != null) {
    validateFilterForJavaScript(filter);
  }
}

private void validateFilterForJavaScript(DimFilter filter)
{
  if (filter instanceof JavaScriptDimFilter) {
    throw new ISE(
        "JavaScript filters are not allowed in the sampler endpoint. "
        + "JavaScript execution is disabled by default for security reasons. "
        + "If you need to use JavaScript filters, enable it via the 'druid.javascript.enabled' configuration "
        + "and use the standard query interface instead of the sampler endpoint."
    );
  }
}

